/** The dial channel this artist sits on — same classifier the stations use. */
function channelForArtist(artist) {
  const tracks = artist?.tracks || [];
  const tally = new Map();
  for (const t of tracks) {
    const hit = SCENE_CHANNELS.find((c) => typeof c.match === "function" && c.match(t));
    if (hit) tally.set(hit.id, (tally.get(hit.id) || 0) + 1);
  }
  const topId = [...tally.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
  return SCENE_CHANNELS.find((c) => c.id === topId) || null;
}

/**
 * Liner notes for an artist, read off the catalog — never written for them.
 * Years, tempo, keys and play counts are facts the crate already holds; a
 * fabricated biography is not.
 */
function artistFile(artist) {
  const tracks = artist?.tracks || [];
  const years = tracks
    .map((t) => parseInt(String(t.year || t.releaseYear || t.releaseDate || "").slice(0, 4), 10))
    .filter((y) => y >= 1900 && y <= 2100)
    .sort((a, b) => a - b);
  const bpms = tracks.map((t) => Number(t.bpm)).filter((b) => b > 0).sort((a, b) => a - b);
  const keys = [...new Set(tracks.map((t) => t.camelot).filter(Boolean))];
  const rows = [];

  if (years.length) {
    const lo = years[0];
    const hi = years[years.length - 1];
    rows.push(["Years", lo === hi ? String(lo) : `${lo}–${hi}`]);
  }
  if (bpms.length) {
    const lo = bpms[0];
    const hi = bpms[bpms.length - 1];
    rows.push(["Tempo", lo === hi ? `${lo} BPM` : `${lo}–${hi} BPM`]);
  }
  if (keys.length) rows.push(["Keys", keys.slice(0, 4).join(" · ")]);
  if (artist?.totalPlays > 0) rows.push(["Spins", String(artist.totalPlays)]);
  if (artist?.liked > 0) rows.push(["In crates", `${artist.liked} liked`]);
  return rows;
}

/**
 * Same shelf — other artists the dial files on this artist's channel.
 * The rabbit hole: an artist page should lead to the next artist, not end.
 */
function sameShelfArtists(artist, tracks = [], channel = null, limit = 12) {
  if (!artist || !channel || !tracks.length) return [];
  return buildArtists(tracks)
    .filter((a) => a.slug !== artist.slug && a.name !== artist.name)
    .filter((a) => channelForArtist(a)?.id === channel.id)
    .slice(0, limit);
}

function SameShelfRail({ artists = [], channel, onOpenArtist }) {
  if (!artists.length || !channel) return null;
  const ink = channel.accent || color.accent;
  return (
    <section aria-label="Same shelf" style={{ padding: "24px 20px 0" }}>
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 12, marginBottom: 12 }}>
        <SectionTitle>Same shelf</SectionTitle>
        <span
          style={{
            ...type.lcd,
            color: ink,
            letterSpacing: 0.12,
            whiteSpace: "nowrap",
          }}
        >
          {formatChannelNum(channel.num)} · {channel.shortTitle || channel.title}
        </span>
      </div>
      <div className="hide-scroll" style={{ display: "flex", gap: 14, overflowX: "auto", paddingBottom: 8 }}>
        {artists.map((a) => (
          <button
            key={a.slug}
            type="button"
            onClick={() => onOpenArtist?.(a.name)}
            aria-label={`Open ${a.name}`}
            style={{
              flexShrink: 0,
              width: 112,
              background: "none",
              border: "none",
              padding: 0,
              cursor: onOpenArtist ? "pointer" : "default",
              textAlign: "left",
              color: color.ink,
            }}
          >
            <div
              style={{
                position: "relative",
                width: 112,
                height: 112,
                overflow: "hidden",
                marginBottom: 8,
                background: color.surfaceRaised,
                borderRadius: 6,
                border: "1px solid rgba(255,255,255,0.08)",
              }}
            >
              {a.coverTrack ? <AlbumArt track={a.coverTrack} size={112} borderRadius={6} /> : null}
              <span
                aria-hidden="true"
                style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 3, background: ink }}
              />
            </div>
            <div style={{ fontSize: 13, fontWeight: 650, fontFamily: fontDisplay, letterSpacing: -0.2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
              {a.name}
            </div>
            <div style={{ fontSize: 11, color: color.muted, marginTop: 3 }}>
              {a.count} track{a.count === 1 ? "" : "s"}
            </div>
          </button>
        ))}
      </div>
    </section>
  );
}

/** Artist destination — name, file, same shelf, albums, tracks. No generated copy. */
export default function ArtistPage({
  artist,
  onBack,
  onPlay,
  onOpenAlbum,
  onOpenArtist = null,
  tracks = [],
  currentTrack,
  isPlaying,
  onLike,
  playlistCtx,
}) {
  const channelForShelf = useMemo(() => (artist ? channelForArtist(artist) : null), [artist]);
  const shelf = useMemo(
    () => sameShelfArtists(artist, tracks, channelForShelf),
    [artist, tracks, channelForShelf]
  );
  if (!artist) {
    return (
      <EmptyEntity
        title="Artist not found"
        body="This name isn’t in the catalog yet."
        onBack={onBack}
      />
    );
  }

  const cover = artist.coverTrack;
  const n = artist.count || 0;
  const channel = channelForArtist(artist);
  const ink = channel?.accent || null;
  const file = artistFile(artist);
  const scene = channel?.title || displayGenre(artist.topGenre);

  return (
    <div style={{ minHeight: "100%", maxWidth: 640, margin: "0 auto", width: "100%", animation: "fadeIn 0.28s ease both", fontFamily: font }}>
      <EntityHero
        onBack={onBack}
        title={artist.name}
        meta={`${n} track${n === 1 ? "" : "s"}${scene ? ` · ${scene}` : ""}`}
        coverUrl={cover?.albumCover}
        onPlay={() => cover && onPlay(cover, artist.tracks)}
      />

      {/* Liner notes — printed off the crate, not written for the artist. */}
      {(file.length > 0 || channel) && (
        <section style={{ padding: "16px 20px 0" }}>
          <div
            style={{
              position: "relative",
              overflow: "hidden",
              borderRadius: radio.radiusLcd,
              background: radio.lcdFace,
              border: radio.lcdBorder,
              boxShadow: radio.lcdShadow,
              padding: "14px 16px 14px 18px",
            }}
          >
            <span
              aria-hidden="true"
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                bottom: 0,
                width: 4,
                background: ink || "rgba(183,228,238,0.3)",
              }}
            />
            <div
              style={{
                display: "flex",
                alignItems: "baseline",
                justifyContent: "space-between",
                gap: 12,
                marginBottom: file.length ? 10 : 0,
              }}
            >
              <span
                style={{
                  fontFamily: fontMono,
                  fontSize: 11,
                  fontWeight: 700,
                  letterSpacing: 0.2,
                  textTransform: "uppercase",
                  color: neons.phosphor,
                }}
              >
                On file
              </span>
              {channel && (
                <span
                  style={{
                    fontFamily: fontMono,
                    fontSize: 11,
                    fontWeight: 700,
                    letterSpacing: 0.16,
                    textTransform: "uppercase",
                    color: ink,
                  }}
                >
                  {`CH-${String(channel.num).padStart(2, "0")} ${channel.title}`}
                </span>
              )}
            </div>

            {file.length > 0 && (
              <dl
                style={{
                  margin: 0,
                  display: "grid",
                  gridTemplateColumns: "auto 1fr",
                  columnGap: 14,
                  rowGap: 5,
                }}
              >
                {file.map(([label, value]) => (
                  <div key={label} style={{ display: "contents" }}>
                    <dt
                      style={{
                        fontFamily: fontMono,
                        fontSize: 11,
                        fontWeight: 700,
                        letterSpacing: 0.16,
                        textTransform: "uppercase",
                        color: color.lcdMute,
                      }}
                    >
                      {label}
                    </dt>
                    <dd
                      style={{
                        margin: 0,
                        fontFamily: fontMono,
                        fontSize: 11,
                        fontWeight: 600,
                        letterSpacing: 0.06,
                        color: color.lcdInk,
                      }}
                    >
                      {value}
                    </dd>
                  </div>
                ))}
              </dl>
            )}
          </div>
        </section>
      )}

      <SameShelfRail artists={shelf} channel={channelForShelf} onOpenArtist={onOpenArtist} />

      {artist.albums?.length > 0 && (
        <section style={{ padding: "24px 20px 8px" }}>
          <SectionTitle>Albums</SectionTitle>
          <div className="hide-scroll" style={{ display: "flex", gap: 14, overflowX: "auto", paddingBottom: 8 }}>
            {artist.albums.map((al) => (
              <button
                key={al.slug}
                type="button"
                onClick={() => onOpenAlbum?.(al.slug)}
                style={{
                  flexShrink: 0,
                  width: 140,
                  background: "none",
                  border: "none",
                  padding: 0,
                  cursor: onOpenAlbum ? "pointer" : "default",
                  textAlign: "left",
                  color: color.ink,
                }}
              >
                <div style={{ width: 140, height: 140, overflow: "hidden", marginBottom: 10, background: color.surfaceRaised, borderRadius: 8 }}>
                  {al.coverTrack ? (
                    <AlbumArt track={al.coverTrack} size={140} borderRadius={8} />
                  ) : null}
                </div>
                <div style={{ fontSize: 13, fontWeight: 650, fontFamily: fontDisplay, letterSpacing: -0.2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                  {al.title}
                </div>
                <div style={{ fontSize: 11, color: color.muted, marginTop: 3 }}>{al.count} tracks</div>
              </button>
            ))}
          </div>
        </section>
      )}

      <section style={{ padding: "20px 16px 40px" }}>
        <SectionTitle>Tracks</SectionTitle>
        {artist.tracks.map((t) => (
          <TrackRow
            key={t.id}
            track={t}
            onPlay={() => onPlay(t, artist.tracks)}
            active={currentTrack?.id === t.id}
            isPlaying={isPlaying}
            onLike={onLike}
            playlistCtx={playlistCtx}
          />
        ))}
      </section>
    </div>
  );
}

function formatClock(sec) {
  const n = Math.max(0, Math.round(Number(sec) || 0));
  if (!n) return "";
  const m = Math.floor(n / 60);
  const s = n % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

function albumMeta(album) {
  const tracks = album?.tracks || [];
  const n = album?.count || tracks.length || 0;
  const bits = [`${n} track${n === 1 ? "" : "s"}`];
  const total = tracks.reduce((s, t) => s + (Number(t.duration) || 0), 0);
  if (total >= 60) bits.push(`${Math.round(total / 60)} min`);
  if (album?.avgBpm) bits.push(`${album.avgBpm} BPM`);
  const key = tracks.map((t) => t.camelot).find(Boolean);
  if (key) bits.push(key);
  const year = tracks.map((t) => t.year || t.releaseYear).find(Boolean);
  if (year) bits.push(String(year));
  return bits.join(" · ");
}

/**
 * Album page — one sleeve, title, play, tracklist.
 * No blur wash, no generated story, no repeated cover on every row.
 */
export function AlbumPage({
  album,
  onBack,
  onPlay,
  onOpenArtist,
  currentTrack,
  isPlaying: isPlayingProp,
  onLike,
  playlistCtx,
}) {
  const transportPlaying = useIsPlaying();
  const isPlaying = isPlayingProp ?? transportPlaying;
  const { menu, openFromButton, openFromContext, close } = useTrackMenu();

  if (!album) {
    return (
      <EmptyEntity
        title="Album not found"
        body="This album isn’t in the catalog yet."
        onBack={onBack}
      />
    );
  }

  const cover = album.coverTrack;
  const coverUrl = cover?.albumCover || null;
  const tracks = album.tracks || [];
  const albumArtist = album.artist || "";

  return (
    <div style={{ minHeight: "100%", maxWidth: 640, margin: "0 auto", width: "100%", animation: "fadeIn 0.22s ease both", fontFamily: font }}>
      <div style={{ padding: "16px 20px 20px" }}>
        <button
          type="button"
          onClick={onBack}
          style={{
            background: "none",
            border: "none",
            padding: "8px 0",
            marginBottom: 16,
            color: color.body,
            fontFamily: font,
            fontSize: 14,
            fontWeight: 600,
            cursor: "pointer",
          }}
        >
          ← Back
        </button>

        <div
          style={{
            display: "flex",
            gap: 16,
            alignItems: "flex-end",
          }}
        >
          {coverUrl ? (
            <div
              style={{
                width: 132,
                height: 132,
                flexShrink: 0,
                borderRadius: 8,
                overflow: "hidden",
                background: color.surfaceRaised,
                border: `1px solid ${glass.border}`,
                boxShadow: artShadow.quiet,
              }}
            >
              <CoverImage src={coverUrl} alt="" width={132} height={132} priority />
            </div>
          ) : null}
          <div style={{ minWidth: 0, flex: 1 }}>
            <h1
              style={{
                margin: 0,
                fontSize: "clamp(22px, 6vw, 32px)",
                fontWeight: 700,
                letterSpacing: -0.8,
                fontFamily: fontDisplay,
                color: color.ink,
                lineHeight: 1.08,
              }}
            >
              {album.title}
            </h1>
            {albumArtist ? (
              <button
                type="button"
                onClick={() => onOpenArtist?.(album.artistSlug || albumArtist)}
                style={{
                  background: "none",
                  border: "none",
                  padding: 0,
                  marginTop: 8,
                  color: color.accent,
                  fontSize: 15,
                  fontWeight: 600,
                  cursor: onOpenArtist ? "pointer" : "default",
                }}
              >
                {albumArtist}
              </button>
            ) : null}
            <div style={{
              marginTop: 8,
              fontFamily: fontMono,
              fontSize: 11,
              fontWeight: 700,
              letterSpacing: 0.12,
              textTransform: "uppercase",
              color: color.accent,
            }}>
              {albumMeta(album)}
            </div>
            {cover && (
              <button
                type="button"
                className="play-primary"
                onClick={() => onPlay(cover, tracks)}
                style={{
                  ...BTN_PRIMARY,
                  width: "auto",
                  marginTop: 14,
                  minHeight: 40,
                  padding: "0 16px",
                  borderRadius: 8,
                  fontSize: 14,
                  fontWeight: 650,
                  display: "inline-flex",
                  alignItems: "center",
                  gap: 8,
                }}
              >
                <Icon name="play" size={14} />
                Play
              </button>
            )}
          </div>
        </div>
      </div>

      <ol style={{ listStyle: "none", margin: 0, padding: "4px 8px 40px" }}>
        {tracks.map((t, i) => {
          const active = currentTrack?.id === t.id;
          const guest = t.artist && albumArtist && t.artist !== albumArtist ? t.artist : "";
          const clock = formatClock(t.duration);
          return (
            <li key={t.id} style={{ position: "relative" }}>
              <div
                role="button"
                tabIndex={0}
                aria-label={`Play ${t.title}`}
                onClick={() => onPlay(t, tracks)}
                onContextMenu={(e) => openFromContext(e, t)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    onPlay(t, tracks);
                  }
                }}
                style={{
                  display: "grid",
                  gridTemplateColumns: `28px minmax(0, 1fr) ${clock ? "44px" : "0px"} auto auto`,
                  alignItems: "center",
                  gap: 4,
                  minHeight: 44,
                  padding: "6px 8px",
                  borderRadius: 8,
                  cursor: "pointer",
                  background: active ? "rgba(216,223,232,0.06)" : "transparent",
                  color: color.ink,
                }}
              >
                <span
                  style={{
                    fontFamily: fontMono,
                    fontSize: 11,
                    fontVariantNumeric: "tabular-nums",
                    color: active ? color.accent : color.faint,
                    textAlign: "right",
                    paddingRight: 6,
                  }}
                >
                  {active && isPlaying ? "▶" : String(i + 1).padStart(2, "0")}
                </span>
                <span style={{ minWidth: 0 }}>
                  <span
                    style={{
                      display: "block",
                      fontSize: 14,
                      fontWeight: active ? 650 : 500,
                      letterSpacing: -0.15,
                      color: active ? color.accent : color.ink,
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {t.title}
                  </span>
                  {guest ? (
                    <span
                      style={{
                        display: "block",
                        marginTop: 2,
                        fontSize: 12,
                        color: color.muted,
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {guest}
                    </span>
                  ) : null}
                </span>
                {clock ? (
                  <span
                    style={{
                      fontFamily: fontMono,
                      fontSize: 11,
                      fontVariantNumeric: "tabular-nums",
                      color: color.faint,
                      textAlign: "right",
                    }}
                  >
                    {clock}
                  </span>
                ) : null}
                {onLike ? (
                  <button
                    type="button"
                    aria-label={t.liked ? "Unlike" : "Like"}
                    onClick={(e) => {
                      e.stopPropagation();
                      onLike(t.id);
                    }}
                    style={{
                      background: "none",
                      border: "none",
                      cursor: "pointer",
                      color: t.liked ? color.accent : color.faint,
                      padding: 8,
                    }}
                  >
                    <Icon name={t.liked ? "heart" : "heartempty"} size={16} />
                  </button>
                ) : (
                  <span />
                )}
                <TrackMoreButton onClick={(e) => openFromButton(e, t)} />
              </div>
            </li>
          );
        })}
      </ol>

      {menu && (
        <TrackActionsMenu
          track={menu.track}
          playlistCtx={playlistCtx}
          activePlaylistId={menu.activePlaylistId}
          x={menu.x}
          y={menu.y}
          onClose={close}
        />
      )}
    </div>
  );
}

